{
 "summary": "The main theorem is Theorem 1.1. Let S ⊂ ℝⁿ be convex and compact with nonempty interior and barycenter 0, and suppose the only lattice point in int S is 0. Then the Lebesgue volume of S is at most (n+1)ⁿ/n!. Separate results show that the centered simplex (n+1)Δₙ − 𝟙 has barycenter 0 and volume (n+1)ⁿ/n!, and that some admissible body attains the bound. No substantive caveat was found; the most notable minor point is that the sharpness statement is existential and does not say the extremizer is the simplex.",
 "glossary": [
  {"decl": "Ehrhart.standardSimplex", "line": 15, "plain": "Δₙ = {x : xᵢ ≥ 0 for all i, Σxᵢ ≤ 1} = conv{0, e₁, …, eₙ}", "standard_concept": "standard simplex Δₙ", "matches_standard": "yes", "note": ""},
  {"decl": "Ehrhart.simplexDilation", "line": 18, "plain": "x ↦ (n+1)x − (1, …, 1)", "standard_concept": "affine map sending Δₙ to the centered simplex", "matches_standard": "yes", "note": ""},
  {"decl": "Ehrhart.centeredSimplex", "line": 21, "plain": "(n+1)Δₙ − (1, …, 1)", "standard_concept": "the paper's extremal simplex", "matches_standard": "yes", "note": ""},
  {"decl": "Ehrhart.normalizedVolume", "line": 24, "plain": "Lebesgue volume of K as a real number (toReal; 0 if infinite)", "standard_concept": "vol(K)", "matches_standard": "yes", "note": "The name says 'normalized' but it is ordinary volume, which is what the paper uses. Bodies are compact, so the volume is finite."},
  {"decl": "Ehrhart.barycenter", "line": 27, "plain": "vol(K)⁻¹ ∫_K x dx", "standard_concept": "barycenter (centroid)", "matches_standard": "yes", "note": "Junk value 0 when vol(K) = 0, but every use requires nonempty interior, so the volume is positive."},
  {"decl": "Ehrhart.interiorLatticePoints", "line": 30, "plain": "int(K) ∩ ℤⁿ, viewed as a set of integer vectors", "standard_concept": "interior lattice points", "matches_standard": "yes", "note": ""},
  {"decl": "Ehrhart.CenteredBody", "line": 33, "plain": "convex, compact set with nonempty interior, barycenter 0, and int ∩ ℤⁿ = {0}", "standard_concept": "admissible body in Theorem 1.1", "matches_standard": "yes", "note": ""},
  {"decl": "Ehrhart.sharpConstant", "line": 41, "plain": "(n+1)ⁿ/n!", "standard_concept": "Ehrhart constant", "matches_standard": "yes", "note": ""}
 ],
 "lean_claims": [
  {"theorem": "Ehrhart.Volume.ehrhart_volume_inequality_for_sets", "line": 65, "plain": "For every n and every S ⊆ ℝⁿ that is convex, compact, has nonempty interior, has barycenter 0, and satisfies int(S) ∩ ℤⁿ = {0}: vol(S) ≤ (n+1)ⁿ/n!."},
  {"theorem": "Ehrhart.SimplexVolume.barycenter_centeredSimplex", "line": 48, "plain": "For every n, the barycenter of (n+1)Δₙ − 𝟙 is 0."},
  {"theorem": "Ehrhart.SimplexVolume.normalizedVolume_centeredSimplex", "line": 52, "plain": "For n > 0, vol((n+1)Δₙ − 𝟙) = (n+1)ⁿ/n!."},
  {"theorem": "Ehrhart.SimplexVolume.exists_centeredBody_sharp", "line": 56, "plain": "For n > 0, there exists a convex compact body with nonempty interior, barycenter 0 and int ∩ ℤⁿ = {0} whose volume equals (n+1)ⁿ/n!."}
 ],
 "paper_claims": [
  {"ref": "Theorem 1.1", "plain": "Let K ⊂ ℝⁿ be a full-dimensional compact convex body with barycenter 0 and int(K) ∩ ℤⁿ = {0}. Then vol(K) ≤ (n+1)ⁿ/n!."},
  {"ref": "Sharpness remark after Theorem 1.1", "plain": "The simplex (n+1)Δₙ − (1, …, 1) has barycenter 0, has no other interior lattice point, and has volume (n+1)ⁿ/n!."}
 ],
 "coverage": [
  {"paper_ref": "Theorem 1.1", "lean_theorem": "Ehrhart.Volume.ehrhart_volume_inequality_for_sets", "relation": "equivalent", "why": "Hypotheses and conclusion match; hn : 0 ≤ n is vacuous."},
  {"paper_ref": "Sharpness remark after Theorem 1.1", "lean_theorem": "Ehrhart.SimplexVolume.exists_centeredBody_sharp", "relation": "lean_weaker", "why": "Lean asserts only that some extremizer exists. The barycenter and volume of the simplex are proved separately, but no theorem states that the simplex's interior lattice points are exactly {0}."}
 ],
 "flags": [
  {"id": "F1", "category": "coverage", "severity": "low", "decl": "Ehrhart.SimplexVolume.exists_centeredBody_sharp", "line": 56, "paper_ref": "Sharpness remark after Theorem 1.1", "explanation": "The existential statement does not identify the extremizer as the centered simplex. The paper's claim that this simplex has 0 as its only interior lattice point is not stated anywhere. Sharpness of the bound itself is still captured.", "polarity": "lean weaker", "probe_idea": "theorem t (n : ℕ) : interiorLatticePoints (centeredSimplex n) = {0}"},
  {"id": "F2", "category": "other", "severity": "low", "decl": "Ehrhart.Volume.ehrhart_volume_inequality_for_sets", "line": 66, "paper_ref": "Theorem 1.1", "explanation": "The hypothesis hn : 0 ≤ n is vacuous. The n = 0 case is consistent: volume on Fin 0 → ℝ gives the point mass 1, and the bound is 1⁰/0! = 1.", "polarity": "n/a", "probe_idea": null},
  {"id": "F3", "category": "assumption", "severity": "low", "decl": "Ehrhart.SimplexVolume.normalizedVolume_centeredSimplex", "line": 52, "paper_ref": "Sharpness remark after Theorem 1.1", "explanation": "The hypothesis 0 < n is unnecessary but harmless, since the paper's setting has n ≥ 1.", "polarity": "lean weaker", "probe_idea": null}
 ],
 "lint_verdicts": []
}
